div.script:

// Simple Resize functionality
document.addEventListener('DOMContentLoaded', function() {
    var panel = document.getElementById('odoo_chatbot_panel');
    var handles = panel.querySelectorAll('.resize-handle');

    var isResizing = false;
    var currentHandle = null;
    var startX, startY, startWidth, startHeight, startLeft, startTop;

    function addResizeFeedback() {
        panel.classList.add('resizing');
        document.body.style.cursor = currentHandle.style.cursor;
    }

    function removeResizeFeedback() {
        panel.classList.remove('resizing');
        document.body.style.cursor = '';
    }

    for (var i = 0; i < handles.length; i++) {
        var handle = handles[i];
        handle.addEventListener('mousedown', function(e) {
            e.preventDefault();
            e.stopPropagation();
            isResizing = true;
            currentHandle = this;

            var rect = panel.getBoundingClientRect();
            startX = e.clientX;
            startY = e.clientY;
            startWidth = rect.width;
            startHeight = rect.height;
            startLeft = rect.left;
            startTop = rect.top;

            addResizeFeedback();
            document.addEventListener('mousemove', handleMouseMove);
            document.addEventListener('mouseup', handleMouseUp);
        });
    }

    function handleMouseMove(e) {
        if (!isResizing) return;

        var deltaX = e.clientX - startX;
        var deltaY = e.clientY - startY;

        var handleClass = currentHandle.className;
        var minWidth = 300;
        var minHeight = 200;
        var maxWidth = window.innerWidth * 0.9;
        var maxHeight = window.innerHeight * 0.8;

        var history = document.querySelector('.chatbot-user-questions');
        if (history) {
            if (panel.style.width === '100vw' &amp;&amp; panel.style.height === '100vh') {
                history.classList.remove('d-none');
            } else {
                history.classList.add('d-none');
            }
        }

        if (handleClass.indexOf('resize-left') !== -1) {
            var newWidth = startWidth - deltaX;
            if (newWidth >= minWidth &amp;&amp; newWidth <= maxWidth) {
                panel.style.width = newWidth + 'px';
                panel.style.left = (startLeft + deltaX) + 'px';
            }
        } else if (handleClass.indexOf('resize-right') !== -1) {
            var newWidth = startWidth + deltaX;
            if (newWidth >= minWidth &amp;&amp; newWidth <= maxWidth) {
                panel.style.width = newWidth + 'px';
            }
        } else if (handleClass.indexOf('resize-top') !== -1) {
            var newHeight = startHeight - deltaY;
            if (newHeight >= minHeight &amp;&amp; newHeight <= maxHeight) {
                panel.style.height = newHeight + 'px';
                panel.style.top = (startTop + deltaY) + 'px';
            }
        } else if (handleClass.indexOf('resize-bottom') !== -1) {
            var newHeight = startHeight + deltaY;
            if (newHeight >= minHeight &amp;&amp; newHeight <= maxHeight) {
                panel.style.height = newHeight + 'px';
            }
        } else if (handleClass.indexOf('resize-tl') !== -1) {
            var newWidth = startWidth - deltaX;
            var newHeight = startHeight - deltaY;
            if (newWidth >= minWidth &amp;&amp; newWidth <= maxWidth &amp;&amp; newHeight >= minHeight &amp;&amp; newHeight <= maxHeight) {
                panel.style.width = newWidth + 'px';
                panel.style.height = newHeight + 'px';
                panel.style.left = (startLeft + deltaX) + 'px';
                panel.style.top = (startTop + deltaY) + 'px';
            }
        } else if (handleClass.indexOf('resize-tr') !== -1) {
            var newWidth = startWidth + deltaX;
            var newHeight = startHeight - deltaY;
            if (newWidth >= minWidth &amp;&amp; newWidth <= maxWidth &amp;&amp; newHeight >= minHeight &amp;&amp; newHeight <= maxHeight) {
                panel.style.width = newWidth + 'px';
                panel.style.height = newHeight + 'px';
                panel.style.top = (startTop + deltaY) + 'px';
            }
        } else if (handleClass.indexOf('resize-bl') !== -1) {
            var newWidth = startWidth - deltaX;
            var newHeight = startHeight + deltaY;
            if (newWidth >= minWidth &amp;&amp; newWidth <= maxWidth &amp;&amp; newHeight >= minHeight &amp;&amp; newHeight <= maxHeight) {
                panel.style.width = newWidth + 'px';
                panel.style.height = newHeight + 'px';
                panel.style.left = (startLeft + deltaX) + 'px';
            }
        } else if (handleClass.indexOf('resize-br') !== -1) {
            var newWidth = startWidth + deltaX;
            var newHeight = startHeight + deltaY;
            if (newWidth >= minWidth &amp;&amp; newWidth <= maxWidth &amp;&amp; newHeight >= minHeight &amp;&amp; newHeight <= maxHeight) {
                panel.style.width = newWidth + 'px';
                panel.style.height = newHeight + 'px';
            }
        }
    }

    function handleMouseUp() {
        isResizing = false;
        currentHandle = null;
        removeResizeFeedback();
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
    }

    panel.addEventListener('selectstart', function(e) {
        if (isResizing) {
            e.preventDefault();
        }
    });
});

// Global download function - outside CDATA
function downloadReport(dashboard) {
    console.log('downloadReport function called for:', dashboard);

    var buttonId = 'download_' + dashboard + '_report_btn';
    var textId = 'download_' + dashboard + '_text';
    var loaderId = 'download_' + dashboard + '_loader';
    var messageId = 'download_' + dashboard + '_message';

    var button = document.getElementById(buttonId);
    var textSpan = document.getElementById(textId);
    var loaderSpan = document.getElementById(loaderId);
    var messageDiv = document.getElementById(messageId);

    if (button && textSpan && loaderSpan) {
        // Show loader
        button.disabled = true;
        textSpan.style.display = 'none';
        loaderSpan.style.display = 'inline';
    }

    // Show red message
    if (messageDiv) {
        messageDiv.style.display = 'block';
    }

    // Get URL parameters
    var urlParams = new URLSearchParams(window.location.search);
    var url = '/predictive_engine/dashboard_report?dashboard=' + dashboard;

    if (urlParams.get('date_filter')) url += '&date_filter=' + urlParams.get('date_filter');
    if (urlParams.get('year_filter')) url += '&year_filter=' + urlParams.get('year_filter');
    if (urlParams.get('date_from')) url += '&date_from=' + urlParams.get('date_from');
    if (urlParams.get('date_to')) url += '&date_to=' + urlParams.get('date_to');

    // Use XMLHttpRequest to track actual download completion
    var xhr = new XMLHttpRequest();
    xhr.open('GET', url, true);
    xhr.responseType = 'blob';

    xhr.onprogress = function(e) {
        // Show progress if available
        if (e.lengthComputable) {
            var percentComplete = (e.loaded / e.total) * 100;
            console.log('Download progress: ' + percentComplete + '%');
        }
    };

    xhr.onload = function() {
        if (xhr.status === 200) {
            // Download successful
            var blob = xhr.response;
            var cd = xhr.getResponseHeader('Content-Disposition');
            var filename = (dashboard === 'crm' ? 'CRM' : 'Sales') + '_dashboard_report.pdf';

            // Extract filename from Content-Disposition header if available
            if (cd) {
                var matches = /filename="(.+)"/.exec(cd);
                if (matches) filename = matches[1];
            }

            // Create download link
            var link = document.createElement('a');
            var urlObj = window.URL.createObjectURL(blob);
            link.href = urlObj;
            link.download = filename;
            link.style.display = 'none';
            document.body.appendChild(link);

            // Hide message immediately when download starts
            if (messageDiv) {
                messageDiv.style.display = 'none';
            }

            // Trigger download
            link.click();

            // Clean up and hide loader after download is triggered
            setTimeout(function() {
                try {
                    window.URL.revokeObjectURL(urlObj);
                    document.body.removeChild(link);
                } catch(e) {
                    console.log('Error cleaning up:', e);
                }

                // Hide loader
                if (button && textSpan && loaderSpan) {
                    button.disabled = false;
                    textSpan.style.display = 'inline';
                    loaderSpan.style.display = 'none';
                }
            }, 1000);
        } else {
            // Error occurred
            console.error('Download failed:', xhr.status, xhr.statusText);
            alert('Failed to generate report: ' + (xhr.statusText || ('HTTP ' + xhr.status)));

            // Hide loader and message on error
            if (button && textSpan && loaderSpan) {
                button.disabled = false;
                textSpan.style.display = 'inline';
                loaderSpan.style.display = 'none';
            }
            if (messageDiv) {
                messageDiv.style.display = 'none';
            }
        }
    };

    xhr.onerror = function() {
        console.error('Network error while downloading report');
        alert('Network error while downloading report');

        // Hide loader and message on error
        if (button && textSpan && loaderSpan) {
            button.disabled = false;
            textSpan.style.display = 'inline';
            loaderSpan.style.display = 'none';
        }
        if (messageDiv) {
            messageDiv.style.display = 'none';
        }
    };

    // Start the download
    xhr.send();
}

// Make function globally accessible
window.downloadReport = downloadReport;

// Test function availability
console.log('downloadReport function available:', typeof downloadReport);
console.log('window.downloadReport available:', typeof window.downloadReport);



// Report downloader with progress (Sales/Shared)
(function(){
    // Simple global spin controller
    window.ReportSpin = window.ReportSpin || {
        show: function(){ try{ var m=document.getElementById('report_spinner_modal'); if(m) m.style.display='flex'; }catch(e){} },
        hide: function(){ try{ var m=document.getElementById('report_spinner_modal'); if(m) m.style.display='none'; }catch(e){} }
    };
    function buildReportUrl(dashboard, filters){
        return '/predictive_engine/dashboard_report?dashboard=' + encodeURIComponent(dashboard)
            + '&date_filter=' + encodeURIComponent(filters.date_filter || '')
            + '&year_filter=' + encodeURIComponent(filters.year_filter || '')
            + '&date_from=' + encodeURIComponent(filters.date_from || '')
            + '&date_to=' + encodeURIComponent(filters.date_to || '');
    }
    function getFilters(defaultNodeId){
        var params = new URLSearchParams(window.location.search);
        var defNode = document.getElementById(defaultNodeId);
        return {
            date_filter: params.get('date_filter') || (defNode ? defNode.getAttribute('data-current_filter') : '') || '6months',
            year_filter: params.get('year_filter') || (defNode ? defNode.getAttribute('data-selected_year') : '') || '',
            date_from: params.get('date_from') || (defNode ? defNode.getAttribute('data-date_from') : '') || '',
            date_to: params.get('date_to') || (defNode ? defNode.getAttribute('data-date_to') : '') || ''
        };
    }
    function filenameFromDisposition(hdr, fallback){
        try{
            if(!hdr) return fallback;
            var m = /filename\*=UTF-8''([^;]+)|filename=\"?([^\";]+)\"?/i.exec(hdr);
            var fn = (m &amp;&amp; (m[1] || m[2])) || fallback;
            return decodeURIComponent(fn);
        }catch(e){ return fallback; }
    }
    function showModal(){ var m=document.getElementById('report_progress_modal'); if(m){ m.style.display='block'; setProgress(1);} }
    function hideModal(){ var m=document.getElementById('report_progress_modal'); if(m){ m.style.display='none'; } }
    function setProgress(p){
        try{
            var bar=document.getElementById('report_progress_bar');
            var lbl=document.getElementById('report_progress_label');
            p = Math.max(1, Math.min(100, Math.floor(p)));
            if(bar) bar.style.width = p + '%';
            if(lbl) lbl.textContent = p + '%';
        }catch(e){}
    }
    window.DashReport = {
        download: function(dashboard){
            try{
                var filters = getFilters(dashboard === 'crm' ? 'ai_defaults_crm' : 'ai_defaults_sales');
                var url = buildReportUrl(dashboard, filters);

                // Get button elements to reset loader after download
                var buttonId = 'download_' + dashboard + '_report_btn';
                var textId = 'download_' + dashboard + '_text';
                var loaderId = 'download_' + dashboard + '_loader';
                var messageId = 'download_' + dashboard + '_message';
                var btn = document.getElementById(buttonId);
                var txt = document.getElementById(textId);
                var lod = document.getElementById(loaderId);
                var msg = document.getElementById(messageId);

                // Show red message
                if (msg) {
                    msg.style.display = 'block';
                }

                // Show both: indeterminate spinner immediately + progress modal when data flows
                try{ if (window.ReportSpin &amp;&amp; ReportSpin.show) ReportSpin.show(); }catch(e){}
                showModal();
                var xhr = new XMLHttpRequest();
                xhr.open('GET', url, true);
                xhr.responseType = 'blob';
                var last = 1, anim;
                xhr.onprogress = function(e){
                    if (e.lengthComputable) {
                        var pct = (e.loaded / e.total) * 100;
                        last = pct; setProgress(pct);
                    } else {
                        // Indeterminate: animate slowly up to 90%
                        if (!anim) {
                            anim = setInterval(function(){ last = Math.min(90, last + 2); setProgress(last); }, 200);
                        }
                    }
                };
                xhr.onload = function(){
                    try{ if (anim) clearInterval(anim); }catch(e){}
                    if (xhr.status === 200) {
                        setProgress(100);
                        var blob = xhr.response;
                        var cd = xhr.getResponseHeader('Content-Disposition');
                        var fn = filenameFromDisposition(cd, (dashboard==='crm'?'CRM':'Sales') + '_dashboard_report.pdf');
                            var link = document.createElement('a');
                            var urlObj = window.URL.createObjectURL(blob);
                            link.href = urlObj; link.download = fn;
                            document.body.appendChild(link);

                            // Hide message immediately when download starts
                            if (msg) {
                                msg.style.display = 'none';
                            }

                            link.click();
                            setTimeout(function(){ 
                                try{ 
                                    window.URL.revokeObjectURL(urlObj); 
                                    document.body.removeChild(link);
                                }catch(e){} 
                                hideModal(); 
                                try{ if (window.ReportSpin &amp;&amp; ReportSpin.hide) ReportSpin.hide(); }catch(e){} 

                                // Reset button loader state
                                if (btn &amp;&amp; txt &amp;&amp; lod) {
                                    btn.disabled = false;
                                    txt.style.display = 'inline';
                                    lod.style.display = 'none';
                                }
                            }, 1000);
                    } else {
                        setProgress(100);
                        setTimeout(function(){ 
                            try{ hideModal(); }catch(e){} 
                            try{ if (window.ReportSpin &amp;&amp; ReportSpin.hide) ReportSpin.hide(); }catch(e){} 

                            // Reset button loader state on error and hide message
                            if (btn &amp;&amp; txt &amp;&amp; lod) {
                                btn.disabled = false;
                                txt.style.display = 'inline';
                                lod.style.display = 'none';
                            }
                            if (msg) {
                                msg.style.display = 'none';
                            }
                        }, 600);
                        try{ alert('Failed to generate report: ' + (xhr.statusText || ('HTTP ' + xhr.status))); }catch(e){}
                    }
                };
                xhr.onerror = function(){
                    try{ if (anim) clearInterval(anim); }catch(e){}
                    setProgress(100);
                    setTimeout(function(){ 
                        try{ hideModal(); }catch(e){} 
                        try{ if (window.ReportSpin &amp;&amp; ReportSpin.hide) ReportSpin.hide(); }catch(e){} 

                        // Reset button loader state on error and hide message
                        if (btn &amp;&amp; txt &amp;&amp; lod) {
                            btn.disabled = false;
                            txt.style.display = 'inline';
                            lod.style.display = 'none';
                        }
                        if (msg) {
                            msg.style.display = 'none';
                        }
                    }, 600);
                    try{ alert('Network error while downloading report'); }catch(e){}
                };
                xhr.send();
            }catch(err){ 
                try{ alert('Error: ' + err.message); }catch(e){} 

                // Reset button loader on exception and hide message
                var buttonId = 'download_' + dashboard + '_report_btn';
                var textId = 'download_' + dashboard + '_text';
                var loaderId = 'download_' + dashboard + '_loader';
                var messageId = 'download_' + dashboard + '_message';
                var btn = document.getElementById(buttonId);
                var txt = document.getElementById(textId);
                var lod = document.getElementById(loaderId);
                var msg = document.getElementById(messageId);
                if (btn &amp;&amp; txt &amp;&amp; lod) {
                    btn.disabled = false;
                    txt.style.display = 'inline';
                    lod.style.display = 'none';
                }
                if (msg) {
                    msg.style.display = 'none';
                }
            }
        }
    };
    // Minimal inline downloader as a backup if DashReport isn't available when clicking
    window.__salesInlineDownload = function(){
        try{
            if (window.DashReport &amp;&amp; typeof window.DashReport.download==='function'){
                return window.DashReport.download('sales');
            }
            // Show message when download starts
            var msg = document.getElementById('download_sales_message');
            if (msg) {
                msg.style.display = 'block';
            }
            var filters = getFilters('ai_defaults_sales');
            var url = buildReportUrl('sales', filters);
            try{ if (window.ReportSpin &amp;&amp; ReportSpin.show) ReportSpin.show(); }catch(e){}
            showModal();
            var xhr = new XMLHttpRequest();
            xhr.open('GET', url, true);
            xhr.responseType = 'blob';
            var last = 1, anim;
            xhr.onprogress = function(e){
                if (e.lengthComputable) { var pct = (e.loaded / e.total) * 100; last = pct; setProgress(pct); }
                else { if (!anim) { anim = setInterval(function(){ last = Math.min(90, last + 2); setProgress(last); }, 200); } }
            };
            xhr.onload = function(){
                try{ if (anim) clearInterval(anim); }catch(e){}
                if (xhr.status === 200) {
                    setProgress(100);
                    var blob = xhr.response;
                    var cd = xhr.getResponseHeader('Content-Disposition');
                    var fn = filenameFromDisposition(cd, 'Sales_dashboard_report.pdf');
                    var link = document.createElement('a');
                    var urlObj = window.URL.createObjectURL(blob);
                    link.href = urlObj; link.download = fn; 
                    document.body.appendChild(link);

                    // Hide message immediately when download starts
                    var msg = document.getElementById('download_sales_message');
                    if (msg) {
                        msg.style.display = 'none';
                    }

                    link.click();
                    setTimeout(function(){ try{ window.URL.revokeObjectURL(urlObj); document.body.removeChild(link);}catch(e){} hideModal(); try{ if (window.ReportSpin &amp;&amp; ReportSpin.hide) ReportSpin.hide(); }catch(e){} }, 600);
                } else { 
                    setProgress(100); 
                    // Hide message on error
                    var msg = document.getElementById('download_sales_message');
                    if (msg) {
                        msg.style.display = 'none';
                    }
                    setTimeout(function(){ try{ hideModal(); }catch(e){} try{ if (window.ReportSpin &amp;&amp; ReportSpin.hide) ReportSpin.hide(); }catch(e){} }, 600); 
                    try{ alert('Failed to generate report'); }catch(e){} 
                }
            };
            xhr.onerror = function(){ 
                try{ if (anim) clearInterval(anim); }catch(e){} 
                setProgress(100); 
                // Hide message on error
                var msg = document.getElementById('download_sales_message');
                if (msg) {
                    msg.style.display = 'none';
                }
                setTimeout(function(){ try{ hideModal(); }catch(e){} try{ if (window.ReportSpin &amp;&amp; ReportSpin.hide) ReportSpin.hide(); }catch(e){} }, 600); 
            };
            xhr.send();
        }catch(e){ try{ var a=document.getElementById('download_sales_report_btn'); if(a &amp;&amp; a.href) window.open(a.href,'_blank'); }catch(_){} }
    };
    // Bind Sales button with fallback navigation
    try {
        document.addEventListener('DOMContentLoaded', function(){
            var btn = document.getElementById('download_sales_report_btn');
            if (!btn) return;
            btn.addEventListener('click', function(){
                try{ window.__salesInlineDownload(); }catch(e){ try { var base = btn.getAttribute('data-fallback-url') || '/predictive_engine/dashboard_report?dashboard=sales'; window.open(base,'_blank'); } catch(_) {} }
            });
        });
    } catch(e) {}
})();
document.addEventListener('DOMContentLoaded', function() {
    var dateSelect = document.getElementById('crm_date_filter_select');
    var yearBox = document.getElementById('crm_year_filter_container');
    var customBox = document.getElementById('crm_custom_date_container');
    function updateCRMFilters() {
        if (!dateSelect) return;
        if (dateSelect.value === 'year') {
            if (yearBox) yearBox.style.display = 'block';
            if (customBox) customBox.style.display = 'none';
            // Auto-open year dropdown
            try {
                var yearSelect = yearBox &amp;&amp; yearBox.querySelector('select[name="year_filter"]');
                // If the year select is not present (e.g., hidden by server-side condition), create it dynamically.
                if (!yearSelect &amp;&amp; yearBox) {
                    yearSelect = document.createElement('select');
                    yearSelect.name = 'year_filter';
                    yearSelect.className = 'form-control';
                    yearSelect.size = 4;
                    yearSelect.style.cssText = 'width: 100%; padding: 10px; border-radius: 6px; border: 1px solid #dee2e6;';
                    var years = ['2025','2024','2023','2022'];
                    years.forEach(function(y){
                        var opt = document.createElement('option');
                        opt.value = y; opt.textContent = y;
                        yearSelect.appendChild(opt);
                    });
                    yearBox.appendChild(yearSelect);
                }
                if (yearSelect) {
                    yearSelect.focus();
                    var evt = new MouseEvent('mousedown', { bubbles: true, cancelable: true, view: window });
                    yearSelect.dispatchEvent(evt);
                }
            } catch(e) { /* no-op */ }
        } else if (dateSelect.value === 'custom') {
            if (yearBox) yearBox.style.display = 'none';
            if (customBox) customBox.style.display = 'flex';
        } else {
            if (yearBox) yearBox.style.display = 'none';
            if (customBox) customBox.style.display = 'none';
        }
    }
    if (dateSelect) {
        dateSelect.addEventListener('change', updateCRMFilters);
        // initialize on load so selecting Year instantly shows 2022..2025
        updateCRMFilters();
    }
});

t.script:
document.addEventListener('DOMContentLoaded', function() {
var dateFilterSelect = document.getElementById('date_filter_select');
var yearFilterContainer = document.getElementById('year_filter_container');
var customDateContainer = document.getElementById('custom_date_container');
dateFilterSelect.addEventListener('change', function() {
if (this.value === 'year') {
yearFilterContainer.style.display = 'block';
customDateContainer.style.display = 'none';
} else if (this.value === 'custom') {
yearFilterContainer.style.display = 'none';
customDateContainer.style.display = 'flex';
// Auto-open date picker for From Date if supported
try {
var fromInput = customDateContainer.querySelector('input[name="date_from"]');
if (fromInput) {
fromInput.focus();
if (typeof fromInput.showPicker === 'function') {
fromInput.showPicker();
}
}
} catch(e) { /* no-op */ }
} else {
yearFilterContainer.style.display = 'none';
customDateContainer.style.display = 'none';
}
});
});

                (function(){
                    window.DashAI = {
                        open: function(chartKey){
                            var modal = document.getElementById('ai_insight_modal');
                            var body = document.getElementById('ai_insight_body');
                            var dialog = document.getElementById('ai_insight_dialog');
                            if (!modal || !body) return;
                            modal.style.display = 'block';
                            body.innerHTML = 'Loading...';
                            try { body.style.overflowX = 'hidden'; } catch(e) {}
                            try { body.style.overflowX = 'hidden'; } catch(e) {}
                            try { document.body.setAttribute('data-ai-scroll','1'); document.body.style.overflow='hidden'; } catch(e) {}
                            try { modal.addEventListener('click', function(ev){ if (ev.target === modal){ modal.style.display='none'; try{ document.body.style.overflow=''; document.body.removeAttribute('data-ai-scroll'); }catch(e){} } }); } catch(e) {}
                            try {
                                if (dialog){
                                    dialog.style.width = dialog.getAttribute('data-width') || '95vw';
                                    dialog.style.height = dialog.getAttribute('data-height') || '90vh';
                                    if (!dialog.getAttribute('data-left')){
                                        dialog.style.left = '50%';
                                        dialog.style.top = '5%';
                                        dialog.style.transform = 'translateX(-50%)';
                                    } else {
                                        dialog.style.left = dialog.getAttribute('data-left');
                                        dialog.style.top = dialog.getAttribute('data-top');
                                        dialog.style.transform = 'none';
                                    }
                                }
                            } catch(e) {}
                            var params = new URLSearchParams(window.location.search);
                            var defNode = document.getElementById('ai_defaults_sales') || document.getElementById('ai_defaults_crm');
                            var payload = {
                                chart_key: chartKey,
                                date_filter: params.get('date_filter') || (defNode ? defNode.getAttribute('data-current_filter') : '') || '6months',
                                year_filter: params.get('year_filter') || (defNode ? defNode.getAttribute('data-selected_year') : '') || '',
                                date_from: params.get('date_from') || (defNode ? defNode.getAttribute('data-date_from') : '') || '',
                                date_to: params.get('date_to') || (defNode ? defNode.getAttribute('data-date_to') : '') || '',
                            };
                            fetch('/predictive_engine/chart_insight', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify(payload)
                            }).then(function(r){ return r.json(); }).then(function(resp){
                                console.log('AI Response:', resp);
                                // Get HTML from response (handle both response structures)
                                var insightHtml = (resp && resp.result && resp.result.html) || (resp && resp.html) || '';
                                if (insightHtml){
                                    // Display only insights, pros, and cons - no chart
                                    body.innerHTML = '';
                                    var container = document.createElement('div');
                                    container.style.width = '100%';
                                    container.style.height = '100%';
                                    container.style.overflow = 'auto';
                                    container.style.overflowX = 'hidden';
                                    container.style.overflowY = 'auto';
                                    container.style.padding = '16px';
                                    container.style.paddingRight = '8px';
                                    container.style.wordBreak = 'break-word';
                                    container.style.whiteSpace = 'normal';
                                    container.innerHTML = insightHtml;
                                    body.appendChild(container);
                                } else {
                                    console.log('AI Error - resp:', resp);
                                    body.innerHTML = '
' + (resp && resp.result && resp.result.error ? resp.result.error : 'Failed to generate insights') + '';
                                }
                            }).catch(function(e){
                                console.log('AI Network Error:', e);
                                body.innerHTML = '
' + (e && e.message ? e.message : 'Network error') + '';
                            });
                        }
                    };
                    try {
                        var dialog = document.getElementById('ai_insight_dialog');
                        var header = document.getElementById('ai_insight_header');
                        var resize = document.getElementById('ai_insight_resize');
                        if (dialog && header && resize){
                            var drag = {active:false, x:0, y:0, left:0, top:0};
                            header.addEventListener('mousedown', function(e){
                                e.preventDefault();
                                try { if (e.target && (e.target.tagName === 'BUTTON' || (e.target.closest && e.target.closest('button')))) { return; } } catch(err) {}
                                drag.active = true;
                                drag.x = e.clientX; drag.y = e.clientY;
                                var rect = dialog.getBoundingClientRect();
                                drag.left = rect.left; drag.top = rect.top;
                                dialog.style.transform = 'none';
                                function move(ev){
                                    if (!drag.active) return;
                                    var nl = drag.left + (ev.clientX - drag.x);
                                    var nt = drag.top + (ev.clientY - drag.y);
                                    nl = Math.max(8, Math.min(window.innerWidth - dialog.offsetWidth - 8, nl));
                                    nt = Math.max(8, Math.min(window.innerHeight - dialog.offsetHeight - 8, nt));
                                    dialog.style.left = nl + 'px';
                                    dialog.style.top = nt + 'px';
                                    dialog.setAttribute('data-left', dialog.style.left);
                                    dialog.setAttribute('data-top', dialog.style.top);
                                }
                                function up(){ drag.active = false; document.removeEventListener('mousemove', move); document.removeEventListener('mouseup', up); }
                                document.addEventListener('mousemove', move);
                                document.addEventListener('mouseup', up);
                            });
                            var sizing = {active:false, w:0, h:0, x:0, y:0};
                            resize.addEventListener('mousedown', function(e){
                                e.preventDefault();
                                sizing.active = true; sizing.x = e.clientX; sizing.y = e.clientY;
                                var rect = dialog.getBoundingClientRect(); sizing.w = rect.width; sizing.h = rect.height;
                                function grow(ev){
                                    if (!sizing.active) return;
                                    var nw = Math.max(360, Math.min(window.innerWidth - 32, sizing.w + (ev.clientX - sizing.x)));
                                    var nh = Math.max(220, Math.min(window.innerHeight - 32, sizing.h + (ev.clientY - sizing.y)));
                                    dialog.style.width = nw + 'px';
                                    dialog.style.height = nh + 'px';
                                    dialog.setAttribute('data-width', dialog.style.width);
                                    dialog.setAttribute('data-height', dialog.style.height);
                                }
                                function stop(){ sizing.active = false; document.removeEventListener('mousemove', grow); document.removeEventListener('mouseup', stop); }
                                document.addEventListener('mousemove', grow);
                                document.addEventListener('mouseup', stop);
                            });
                        }
                    } catch(e) {}
                })();

