div.script:

// Simple Resize functionality (CRM)
document.addEventListener('DOMContentLoaded', function() {
    var panel = document.getElementById('odoo_chatbot_panel');
    var handles = panel.querySelectorAll('.resize-handle');
    var isResizing = false;
    var currentHandle = null;
    var startX, startY, startWidth, startHeight, startLeft, startTop;
    function addResizeFeedback() { panel.classList.add('resizing'); document.body.style.cursor = currentHandle.style.cursor; }
    function removeResizeFeedback() { panel.classList.remove('resizing'); document.body.style.cursor = ''; }
    for (var i = 0; i < handles.length; i++) {
        var handle = handles[i];
        handle.addEventListener('mousedown', function(e) {
            e.preventDefault();
            e.stopPropagation();
            isResizing = true;
            currentHandle = this;
            var rect = panel.getBoundingClientRect();
            startX = e.clientX; startY = e.clientY; startWidth = rect.width; startHeight = rect.height; startLeft = rect.left; startTop = rect.top;
            addResizeFeedback();
            document.addEventListener('mousemove', handleMouseMove);
            document.addEventListener('mouseup', handleMouseUp);
        });
    }
    function handleMouseMove(e) {
        if (!isResizing) return;
        var deltaX = e.clientX - startX; var deltaY = e.clientY - startY;
        var handleClass = currentHandle.className; var minWidth = 300; var minHeight = 200; var maxWidth = window.innerWidth * 0.9; var maxHeight = window.innerHeight * 0.8;
        var history = document.querySelector('.chatbot-user-questions');
        if (history) {
            if (panel.style.width === '100vw' && panel.style.height === '100vh') { history.classList.remove('d-none'); } else { history.classList.add('d-none'); }
        }
        if (handleClass.indexOf('resize-left') !== -1) { var newWidth = startWidth - deltaX; if (newWidth >= minWidth && newWidth <= maxWidth) { panel.style.width = newWidth + 'px'; panel.style.left = (startLeft + deltaX) + 'px'; } }
        else if (handleClass.indexOf('resize-right') !== -1) { var newWidth2 = startWidth + deltaX; if (newWidth2 >= minWidth && newWidth2 <= maxWidth) { panel.style.width = newWidth2 + 'px'; } }
        else if (handleClass.indexOf('resize-top') !== -1) { var newHeight = startHeight - deltaY; if (newHeight >= minHeight && newHeight <= maxHeight) { panel.style.height = newHeight + 'px'; panel.style.top = (startTop + deltaY) + 'px'; } }
        else if (handleClass.indexOf('resize-bottom') !== -1) { var newHeight2 = startHeight + deltaY; if (newHeight2 >= minHeight && newHeight2 <= maxHeight) { panel.style.height = newHeight2 + 'px'; } }
        else if (handleClass.indexOf('resize-tl') !== -1) { var nw = startWidth - deltaX; var nh = startHeight - deltaY; if (nw >= minWidth && nw <= maxWidth && nh >= minHeight && nh <= maxHeight) { panel.style.width = nw + 'px'; panel.style.height = nh + 'px'; panel.style.left = (startLeft + deltaX) + 'px'; panel.style.top = (startTop + deltaY) + 'px'; } }
        else if (handleClass.indexOf('resize-tr') !== -1) { var nw2 = startWidth + deltaX; var nh2 = startHeight - deltaY; if (nw2 >= minWidth && nw2 <= maxWidth && nh2 >= minHeight && nh2 <= maxHeight) { panel.style.width = nw2 + 'px'; panel.style.height = nh2 + 'px'; panel.style.top = (startTop + deltaY) + 'px'; } }
        else if (handleClass.indexOf('resize-bl') !== -1) { var nw3 = startWidth - deltaX; var nh3 = startHeight + deltaY; if (nw3 >= minWidth && nw3 <= maxWidth && nh3 >= minHeight && nh3 <= maxHeight) { panel.style.width = nw3 + 'px'; panel.style.height = nh3 + 'px'; panel.style.left = (startLeft + deltaX) + 'px'; } }
        else if (handleClass.indexOf('resize-br') !== -1) { var nw4 = startWidth + deltaX; var nh4 = startHeight + deltaY; if (nw4 >= minWidth && nw4 <= maxWidth && nh4 >= minHeight && nh4 <= maxHeight) { panel.style.width = nw4 + 'px'; panel.style.height = nh4 + 'px'; } }
    }
    function handleMouseUp() { isResizing = false; currentHandle = null; removeResizeFeedback(); document.removeEventListener('mousemove', handleMouseMove); document.removeEventListener('mouseup', handleMouseUp); }
    panel.addEventListener('selectstart', function(e) { if (isResizing) { e.preventDefault(); } });
});


// CRM page: ensure global downloadReport exists (fallback)
if (typeof window.downloadReport !== 'function') {
    window.downloadReport = function(dashboard) {
        try {
            var buttonId = 'download_' + dashboard + '_report_btn';
            var textId = 'download_' + dashboard + '_text';
            var loaderId = 'download_' + dashboard + '_loader';
            var btn = document.getElementById(buttonId);
            var txt = document.getElementById(textId);
            var lod = document.getElementById(loaderId);

            if (btn && txt && lod) { 
                btn.disabled = true; 
                txt.style.display = 'none'; 
                lod.style.display = 'inline'; 
            }

            // Show red message
            var msg = document.getElementById('download_' + dashboard + '_message');
            if (msg) {
                msg.style.display = 'block';
            }

            if (window.DashReport && typeof window.DashReport.download === 'function') {
                return window.DashReport.download(dashboard);
            }

            var params = new URLSearchParams(window.location.search);
            var url = '/predictive_engine/dashboard_report?dashboard=' + dashboard;
            if (params.get('date_filter')) url += '&date_filter=' + params.get('date_filter');
            if (params.get('year_filter')) url += '&year_filter=' + params.get('year_filter');
            if (params.get('date_from')) url += '&date_from=' + params.get('date_from');
            if (params.get('date_to')) url += '&date_to=' + params.get('date_to');

            // Use XMLHttpRequest to track actual download completion
            var xhr = new XMLHttpRequest();
            xhr.open('GET', url, true);
            xhr.responseType = 'blob';

            xhr.onprogress = function(e) {
                // Show progress if available
                if (e.lengthComputable) {
                    var percentComplete = (e.loaded / e.total) * 100;
                    console.log('Download progress: ' + percentComplete + '%');
                }
            };

            xhr.onload = function() {
                if (xhr.status === 200) {
                    // Download successful
                    var blob = xhr.response;
                    var cd = xhr.getResponseHeader('Content-Disposition');
                    var filename = (dashboard === 'crm' ? 'CRM' : 'Sales') + '_dashboard_report.pdf';

                    // Extract filename from Content-Disposition header if available
                    if (cd) {
                        var matches = /filename="(.+)"/.exec(cd);
                        if (matches) filename = matches[1];
                    }

                    // Create download link
                    var link = document.createElement('a');
                    var urlObj = window.URL.createObjectURL(blob);
                    link.href = urlObj;
                    link.download = filename;
                    link.style.display = 'none';
                    document.body.appendChild(link);

                    // Hide message immediately when download starts
                    var msg = document.getElementById('download_' + dashboard + '_message');
                    if (msg) {
                        msg.style.display = 'none';
                    }

                    // Trigger download
                    link.click();

                    // Clean up and hide loader after download is triggered
                    setTimeout(function() {
                        try {
                            window.URL.revokeObjectURL(urlObj);
                            document.body.removeChild(link);
                        } catch(e) {
                            console.log('Error cleaning up:', e);
                        }

                        // Hide loader
                        if (btn && txt && lod) {
                            btn.disabled = false;
                            txt.style.display = 'inline';
                            lod.style.display = 'none';
                        }
                    }, 1000);
                } else {
                    // Error occurred
                    console.error('Download failed:', xhr.status, xhr.statusText);
                    alert('Failed to generate report: ' + (xhr.statusText || ('HTTP ' + xhr.status)));

                    // Hide loader and message on error
                    if (btn && txt && lod) {
                        btn.disabled = false;
                        txt.style.display = 'inline';
                        lod.style.display = 'none';
                    }
                    var msg = document.getElementById('download_' + dashboard + '_message');
                    if (msg) {
                        msg.style.display = 'none';
                    }
                }
            };

            xhr.onerror = function() {
                console.error('Network error while downloading report');
                alert('Network error while downloading report');

                // Hide loader and message on error
                if (btn && txt && lod) {
                    btn.disabled = false;
                    txt.style.display = 'inline';
                    lod.style.display = 'none';
                }
                var msg = document.getElementById('download_' + dashboard + '_message');
                if (msg) {
                    msg.style.display = 'none';
                }
            };

            // Start the download
            xhr.send();
        } catch(err) {
            try { alert('Download error: ' + err.message); } catch(_e) {}
        }
    };
}

// Report downloader with progress (CRM/Shared)
(function(){
    if (window.DashReport) return; // reuse if already defined
    function getFilters(defaultNodeId){
        var params = new URLSearchParams(window.location.search);
        var defNode = document.getElementById(defaultNodeId);
        return {
            date_filter: params.get('date_filter') || (defNode ? defNode.getAttribute('data-current_filter') : '') || '6months',
            year_filter: params.get('year_filter') || (defNode ? defNode.getAttribute('data-selected_year') : '') || '',
            date_from: params.get('date_from') || (defNode ? defNode.getAttribute('data-date_from') : '') || '',
            date_to: params.get('date_to') || (defNode ? defNode.getAttribute('data-date_to') : '') || ''
        };
    }
    function filenameFromDisposition(hdr, fallback){
        try{
            if(!hdr) return fallback;
            var m = /filename\*=UTF-8''([^;]+)|filename=\"?([^\";]+)\"?/i.exec(hdr);
            var fn = (m && (m[1] || m[2])) || fallback;
            return decodeURIComponent(fn);
        }catch(e){ return fallback; }
    }
    // Disable CRM progress modal and percentage (no-op functions)
    function showModal(){ /* progress modal disabled intentionally */ }
    function hideModal(){ /* progress modal disabled intentionally */ }
    function setProgress(p){ /* progress updates disabled */ }
    window.DashReport = {
        download: function(dashboard){
            try{
                var filters = getFilters(dashboard === 'crm' ? 'ai_defaults_crm' : 'ai_defaults_sales');
                var url = '/predictive_engine/dashboard_report?dashboard=' + encodeURIComponent(dashboard)
                    + '&date_filter=' + encodeURIComponent(filters.date_filter || '')
                    + '&year_filter=' + encodeURIComponent(filters.year_filter || '')
                    + '&date_from=' + encodeURIComponent(filters.date_from || '')
                    + '&date_to=' + encodeURIComponent(filters.date_to || '');

                // Get button elements to reset loader after download
                var buttonId = 'download_' + dashboard + '_report_btn';
                var textId = 'download_' + dashboard + '_text';
                var loaderId = 'download_' + dashboard + '_loader';
                var messageId = 'download_' + dashboard + '_message';
                var btn = document.getElementById(buttonId);
                var txt = document.getElementById(textId);
                var lod = document.getElementById(loaderId);
                var msg = document.getElementById(messageId);

                // Show message when download starts
                if (msg) {
                    msg.style.display = 'block';
                }

                showModal();
                var xhr = new XMLHttpRequest();
                xhr.open('GET', url, true);
                xhr.responseType = 'blob';
                var last = 1, anim;
                xhr.onprogress = function(e){ /* progress disabled */ };
                xhr.onload = function(){
                    try{ if (anim) clearInterval(anim); }catch(e){}
                    if (xhr.status === 200) {
                        var blob = xhr.response;
                        var cd = xhr.getResponseHeader('Content-Disposition');
                        var fn = filenameFromDisposition(cd, (dashboard==='crm'?'CRM':'Sales') + '_dashboard_report.pdf');
                        var link = document.createElement('a');
                        var urlObj = window.URL.createObjectURL(blob);
                        link.href = urlObj; link.download = fn;
                        document.body.appendChild(link);

                        // Hide message immediately when download starts
                        if (msg) {
                            msg.style.display = 'none';
                        }

                        link.click();
                        setTimeout(function(){ 
                            try{ 
                                window.URL.revokeObjectURL(urlObj); 
                                document.body.removeChild(link);
                            }catch(e){} 
                            hideModal();

                            // Reset button loader state
                            if (btn && txt && lod) {
                                btn.disabled = false;
                                txt.style.display = 'inline';
                                lod.style.display = 'none';
                            }
                        }, 1000);
                    } else {
                        setProgress(100);
                        setTimeout(function(){
                            hideModal();
                            // Reset button loader state on error and hide message
                            if (btn && txt && lod) {
                                btn.disabled = false;
                                txt.style.display = 'inline';
                                lod.style.display = 'none';
                            }
                            if (msg) {
                                msg.style.display = 'none';
                            }
                        }, 600);
                        try{ alert('Failed to generate report: ' + (xhr.statusText || ('HTTP ' + xhr.status))); }catch(e){}
                    }
                };
                xhr.onerror = function(){
                    try{ if (anim) clearInterval(anim); }catch(e){}
                    setProgress(100);
                    setTimeout(function(){
                        hideModal();
                        // Reset button loader state on error and hide message
                        if (btn && txt && lod) {
                            btn.disabled = false;
                            txt.style.display = 'inline';
                            lod.style.display = 'none';
                        }
                        if (msg) {
                            msg.style.display = 'none';
                        }
                    }, 600);
                    try{ alert('Network error while downloading report'); }catch(e){}
                };
                xhr.send();
            }catch(err){ 
                try{ alert('Error: ' + err.message); }catch(e){} 
                // Reset button loader on exception and hide message
                var buttonId = 'download_' + dashboard + '_report_btn';
                var textId = 'download_' + dashboard + '_text';
                var loaderId = 'download_' + dashboard + '_loader';
                var messageId = 'download_' + dashboard + '_message';
                var btn = document.getElementById(buttonId);
                var txt = document.getElementById(textId);
                var lod = document.getElementById(loaderId);
                var msg = document.getElementById(messageId);
                if (btn && txt && lod) {
                    btn.disabled = false;
                    txt.style.display = 'inline';
                    lod.style.display = 'none';
                }
                if (msg) {
                    msg.style.display = 'none';
                }
            }
        }
    };
})();


(function(){
  var dateSelect = document.getElementById('crm_date_filter_select');
  var yearBox = document.getElementById('crm_year_filter_container');
  var customBox = document.getElementById('crm_custom_date_container');
  function openYearList() {
    if (!yearBox) return;
    var yearSelect = yearBox.querySelector('select[name="year_filter"]');
    if (yearSelect) {
      yearSelect.focus();
      try { yearSelect.size = 4; } catch(e) {}
      try {
        var evt = new MouseEvent('mousedown', { bubbles: true, cancelable: true, view: window });
        yearSelect.dispatchEvent(evt);
      } catch(e) {}
    }
  }
  function openFromDate() {
    if (!customBox) return;
    var fromInput = customBox.querySelector('input[name="date_from"]');
    if (fromInput) {
      fromInput.focus();
      if (typeof fromInput.showPicker === 'function') { try { fromInput.showPicker(); } catch(e) {} }
    }
  }
  function updateCRMFilters(){
    if (!dateSelect) return;
    if (dateSelect.value === 'year'){
      if (yearBox) yearBox.style.display = 'block';
      if (customBox) customBox.style.display = 'none';
      openYearList();
    } else if (dateSelect.value === 'custom'){
      if (yearBox) yearBox.style.display = 'none';
      if (customBox) customBox.style.display = 'flex';
      openFromDate();
    } else {
      if (yearBox) yearBox.style.display = 'none';
      if (customBox) customBox.style.display = 'none';
    }
  }
  if (dateSelect){
    dateSelect.addEventListener('change', updateCRMFilters);
    // Initialize on load
    updateCRMFilters();
  }
  var crmForm = document.getElementById('crm_filter_form');
  if (crmForm){
    crmForm.addEventListener('submit', function(){
      // Hide filter blocks immediately after Apply is clicked
      if (yearBox) yearBox.style.display = 'none';
      if (customBox) customBox.style.display = 'none';
    });
  }
})();

